def factorial(n):
    r = 1
    for i in range(2, n + 1):
        r *= i
    return r

def is_palindrome(s):
    t = ''.join(ch.lower() for ch in s if ch.isalnum())
    return t == t[::-1]

def two_sum(nums, target):
    seen = {}
    for i, v in enumerate(nums):
        if target - v in seen:
            return [seen[target - v], i]
        seen[v] = i
    return []

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a
